package io.aetheris.orchestrator.evaluation;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="aetheris_evaluation_runs") public class EvaluationRunEntity {@Id private UUID id;@Column(nullable=false,length=40) private String subjectType;@Column(nullable=false,length=160) private String subjectId;@Column(nullable=false,length=160) private String scenario;private boolean success;private int corrections;private long latencyMs;private double costUsd;private double evidenceScore;private double hallucinationPenalty;private double overallScore;@Column(nullable=false) private Instant createdAt;protected EvaluationRunEntity(){}public EvaluationRunEntity(UUID id,EvaluationRequest r,double score){this.id=id;this.subjectType=r.subjectType();this.subjectId=r.subjectId();this.scenario=r.scenario();this.success=r.success();this.corrections=Math.max(0,r.corrections());this.latencyMs=Math.max(0,r.latencyMs());this.costUsd=Math.max(0,r.costUsd());this.evidenceScore=clamp(r.evidenceScore());this.hallucinationPenalty=clamp(r.hallucinationPenalty());this.overallScore=clamp(score);this.createdAt=Instant.now();}private double clamp(double v){return Math.max(0,Math.min(100,v));}public UUID getId(){return id;}public String getSubjectType(){return subjectType;}public String getSubjectId(){return subjectId;}public String getScenario(){return scenario;}public boolean isSuccess(){return success;}public int getCorrections(){return corrections;}public long getLatencyMs(){return latencyMs;}public double getCostUsd(){return costUsd;}public double getEvidenceScore(){return evidenceScore;}public double getHallucinationPenalty(){return hallucinationPenalty;}public double getOverallScore(){return overallScore;}public Instant getCreatedAt(){return createdAt;}}
